-- ========================================================
-- NYAUTWA - MASTER DATABASE RESMI (SCHEMA + SEEDERS)
-- 100% Pure MySQL / MariaDB (Siap Import ke phpMyAdmin / cPanel)
-- ========================================================

CREATE TABLE IF NOT EXISTS tenants (id VARCHAR(64) PRIMARY KEY, name VARCHAR(100) NOT NULL, logo VARCHAR(255) NULL, industry VARCHAR(64) DEFAULT 'Bisnis', plan_id VARCHAR(50) DEFAULT 'trial', status VARCHAR(20) DEFAULT 'active', max_devices INT DEFAULT 2, max_messages_monthly INT DEFAULT 1000, max_contacts INT DEFAULT 500, message_limit INT DEFAULT 1000, messages_used INT DEFAULT 0, device_limit INT DEFAULT 2, subscription_ends_at TIMESTAMP NULL, role VARCHAR(30) DEFAULT 'user', webhook_url VARCHAR(255) NULL, is_active TINYINT DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users (id VARCHAR(64) PRIMARY KEY, tenant_id VARCHAR(64) NOT NULL, name VARCHAR(100) NOT NULL, email VARCHAR(100) UNIQUE NOT NULL, phone VARCHAR(32) NULL, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) DEFAULT 'owner', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS devices (id VARCHAR(64) PRIMARY KEY, tenant_id VARCHAR(64) NOT NULL, label VARCHAR(100) NOT NULL, phone VARCHAR(30) NULL, status VARCHAR(20) DEFAULT 'disconnected', session_ref VARCHAR(100) UNIQUE NOT NULL, qr_code TEXT NULL, webhook_url TEXT NULL, webhook_secret VARCHAR(100) NULL, daily_limit INT DEFAULT 1000, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS api_keys (id VARCHAR(64) PRIMARY KEY, tenant_id VARCHAR(64) NOT NULL, name VARCHAR(100) NOT NULL, key_hash VARCHAR(64) NOT NULL, prefix VARCHAR(20) NOT NULL, last_used_at TIMESTAMP NULL, revoked_at TIMESTAMP NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS messages (id VARCHAR(64) PRIMARY KEY, tenant_id VARCHAR(64) NOT NULL, device_id VARCHAR(64) NOT NULL, direction VARCHAR(10) NOT NULL DEFAULT 'outbound', to_from VARCHAR(64) NOT NULL, type VARCHAR(20) NOT NULL DEFAULT 'text', body TEXT NOT NULL, media_ref TEXT NULL, status VARCHAR(20) NOT NULL DEFAULT 'queued', wa_message_id VARCHAR(100) NULL, idempotency_key VARCHAR(100) NULL, error TEXT NULL, is_read TINYINT(1) DEFAULT 0, queued_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, sent_at TIMESTAMP NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS webhook_deliveries (id VARCHAR(64) PRIMARY KEY, tenant_id VARCHAR(64) NOT NULL, device_id VARCHAR(64) NOT NULL, event VARCHAR(50) NOT NULL, payload TEXT NOT NULL, attempts INT NOT NULL DEFAULT 1, last_status INT NULL, next_retry_at TIMESTAMP NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS settings (id VARCHAR(64) PRIMARY KEY, tenant_id VARCHAR(64) NOT NULL, `key` VARCHAR(50) NOT NULL, `value` TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS plans (id VARCHAR(50) PRIMARY KEY, name VARCHAR(100) NOT NULL, limits_json TEXT NOT NULL, price_monthly DECIMAL(12,2) DEFAULT 0, price_yearly DECIMAL(12,2) DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS subscriptions (id VARCHAR(64) PRIMARY KEY, tenant_id VARCHAR(64) NOT NULL, plan_id VARCHAR(50) NOT NULL, status VARCHAR(20) DEFAULT 'active', starts_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, expires_at TIMESTAMP NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS invoices (id VARCHAR(64) PRIMARY KEY, invoice_no VARCHAR(50) NULL, tenant_id VARCHAR(64) NOT NULL, plan_id VARCHAR(50) DEFAULT 'starter', amount DECIMAL(12,2) NOT NULL DEFAULT 0, status VARCHAR(20) DEFAULT 'unpaid', payment_method VARCHAR(50) NULL, payment_method_id VARCHAR(50) NULL, snap_token VARCHAR(255) NULL, paid_at TIMESTAMP NULL, plan_name VARCHAR(100) NULL, period VARCHAR(20) DEFAULT 'monthly', notes TEXT NULL, payment_proof VARCHAR(255) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payment_methods (id VARCHAR(50) PRIMARY KEY, name VARCHAR(100) NOT NULL, account_number VARCHAR(100) NULL, account_name VARCHAR(100) NULL, type VARCHAR(30) DEFAULT 'bank_transfer', is_active INT DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS features (code VARCHAR(50) PRIMARY KEY, name VARCHAR(100) NOT NULL, category VARCHAR(50) DEFAULT 'messaging', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tenant_features (tenant_id VARCHAR(64) NOT NULL, feature_code VARCHAR(50) NOT NULL, enabled INT DEFAULT 1, PRIMARY KEY (tenant_id, feature_code));
CREATE TABLE IF NOT EXISTS usage_counters (tenant_id VARCHAR(64) NOT NULL, period VARCHAR(10) NOT NULL, messages_out INT DEFAULT 0, api_calls INT DEFAULT 0, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (tenant_id, period));
CREATE TABLE IF NOT EXISTS login_attempts (id VARCHAR(64) PRIMARY KEY, email VARCHAR(100) NOT NULL, ip VARCHAR(45) NULL, ip_address VARCHAR(45) NULL, attempts INT DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, last_attempt_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS saas_features (id VARCHAR(36) PRIMARY KEY, code VARCHAR(50) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, description TEXT NULL, is_enabled TINYINT(1) DEFAULT 1, min_plan_tier VARCHAR(20) DEFAULT 'starter', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS landing_configs (id VARCHAR(36) PRIMARY KEY, section_key VARCHAR(50) NOT NULL UNIQUE, config_json LONGTEXT NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tags (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, name VARCHAR(100) NOT NULL, color VARCHAR(20) DEFAULT '#16A36A', created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS contacts (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, tag_id VARCHAR(36) NULL, name VARCHAR(128) NOT NULL, phone VARCHAR(64) NOT NULL, email VARCHAR(128) NULL, notes TEXT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS autoreplies (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, device_id VARCHAR(36) NULL, keyword VARCHAR(255) NOT NULL, match_type VARCHAR(20) DEFAULT 'contain', type VARCHAR(32) DEFAULT 'text', response TEXT NOT NULL, media_url VARCHAR(255) NULL, options TEXT NULL, is_quoted INT DEFAULT 0, is_typing INT DEFAULT 0, delay_seconds INT DEFAULT 1, status VARCHAR(20) DEFAULT 'active', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS campaigns (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, device_id VARCHAR(36) NOT NULL, name VARCHAR(128) NOT NULL, type VARCHAR(32) DEFAULT 'text', message TEXT NOT NULL, media_url VARCHAR(255) NULL, delay_min INT DEFAULT 5, delay_max INT DEFAULT 15, total_recipients INT DEFAULT 0, total_sent INT DEFAULT 0, total_failed INT DEFAULT 0, status VARCHAR(20) DEFAULT 'draft', scheduled_at DATETIME NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS blasts (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, campaign_id VARCHAR(36) NOT NULL, receiver VARCHAR(64) NOT NULL, message TEXT NOT NULL, status VARCHAR(20) DEFAULT 'pending', error_message TEXT NULL, sent_at DATETIME NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS whatsapp_lids (tenant_id VARCHAR(64) NOT NULL, phone VARCHAR(64) NOT NULL, lid VARCHAR(64) NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (tenant_id, lid));
CREATE TABLE IF NOT EXISTS crm_chat_states (tenant_id VARCHAR(64) NOT NULL, phone VARCHAR(64) NOT NULL, autoreply_paused TINYINT(1) DEFAULT 0, needs_human TINYINT(1) DEFAULT 0, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (tenant_id, phone));


